'use strict';
const page=document.getElementById('page');
const qs=new URLSearchParams(location.search);
const safeDate=s=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(s||''))return false;const d=new Date(s+'T00:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===s};
const state={view:['a1','a2','search','detail'].includes(qs.get('view'))?qs.get('view'):'a1',palette:['navy','blue','charcoal'].includes(qs.get('palette'))?qs.get('palette'):'navy',city:qs.get('city')||'제주특별자치도',start:safeDate(qs.get('in'))?qs.get('in'):'2026-11-12',end:safeDate(qs.get('out'))?qs.get('out'):'2026-11-14',guests:Math.max(1,Math.min(2147483647,Number(qs.get('guests'))||2)),room:0,result:'normal',pool:false};
if(state.end<=state.start)state.end=addDays(state.start,1);
const photo='assets/coast-concept.png', roomPhoto='assets/room-concept.png';
const fmt=s=>{const d=new Date(s+'T00:00:00Z');return `${d.getUTCMonth()+1}.${String(d.getUTCDate()).padStart(2,'0')}`};
function addDays(s,n){const d=new Date(s+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)}
const nights=()=>Math.round((Date.parse(state.end)-Date.parse(state.start))/86400000);
const range=()=>`${fmt(state.start)} — ${fmt(state.end)}`;
const currency=n=>new Intl.NumberFormat('ko-KR').format(n);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mast=over=>`<header class="mast ${over?'over-mast':''}"><a href="?view=a1" data-go="a1" class="brand"><span class="brand-mark">R</span><span>RESERVATION<br>PLATFORM</span></a><nav aria-label="사이트 탐색"><a href="?view=search" data-go="search">숙소 둘러보기</a><a href="?view=search" data-go="search">여행의 시작</a><button data-action="login">로그인</button></nav></header>`;
const footer=()=>`<footer class="footer"><div>RESERVATION PLATFORM <span>당신의 다음 머무름을 위해.</span></div><div>DESIGN CONCEPT · 2026<br>전체 숙소·가격·인원·사진은 가상 예시입니다.</div></footer>`;
const searchbar=()=>`<form class="searchbar" aria-label="숙소 검색"><label><b>여행지 · 도시명</b><input name="city" aria-label="여행지" value="${escape(state.city)}" maxlength="100"></label><button type="button" data-action="dates"><b>체크인 — 체크아웃</b><span>${range()} · ${nights()}박</span></button><button type="button" data-action="guests"><b>숙박 인원</b><span>총 ${state.guests}명</span></button><button class="primary" type="submit">숙소 찾기 <span aria-hidden="true">↗</span></button></form>`;
function home(editorial){return `<div class="home-wrap ${editorial?'editorial':''}">${editorial?mast(false)+`<div class="editorial-head"><div><p class="eyebrow">A JOURNEY WORTH STAYING FOR</p><h1>Less rush.<br><em>More room.</em></h1></div><p class="aside-copy">조금 느리게, 조금 더 깊이.<br>머무는 순간이 여행이 되는 곳을 만나세요.</p></div><div class="editorial-photo"><img src="${photo}" alt="가상 리조트의 바다와 수영장, AI 생성 콘셉트 이미지"><span class="photo-credit">AI-GENERATED · FICTIONAL STAY</span></div><div class="editorial-search">${searchbar()}<p class="editorial-note">떠나고 싶은 곳, 머물고 싶은 날짜. 여행은 여기서 시작됩니다.</p></div>`:`${mast(true)}<section class="hero"><img src="${photo}" alt="바다와 석조 리조트가 보이는 AI 생성 콘셉트 이미지"><div><p class="eyebrow">A JOURNEY WORTH STAYING FOR</p><h1>Somewhere<br>you can <em>slow down.</em></h1><p class="hero-ko">일상에서 한 걸음, 당신만의 머무름.<br>마음이 먼저 도착하는 곳을 찾아보세요.</p></div>${searchbar()}<span class="scroll-hint">SCROLL TO EXPLORE ↓</span><span class="photo-credit">AI-GENERATED · FICTIONAL STAY</span></section>`}<section class="section"><div class="section-heading"><div><p class="eyebrow">A DIFFERENT PACE</p><h2>Stay for the feeling.</h2><p>사진 너머, 머물고 싶은 공간을 만나세요.</p></div><a class="text-btn" href="?view=search" data-go="search">모든 숙소 보기 ↗</a></div><div class="explore-grid"><a class="explore-card" href="?view=detail" data-go="detail"><img src="${photo}" alt="가상 숙소 외관 사진"><div class="caption"><div><h3>서해의 여백</h3><small>제주특별자치도 · 서귀포시 · 가상 숙소</small></div><span>↗</span></div></a><a class="explore-card" href="?view=detail" data-go="detail"><img src="${roomPhoto}" alt="가상 객실 내부 사진"><div class="caption"><div><h3>온전히 쉬어가는 공간</h3><small>객실을 충분히 살펴보고 선택하세요.</small></div><span>↗</span></div></a></div></section>${footer()}</div>`}
const stays=[{name:'서해의 여백',loc:'제주특별자치도 · 서귀포시',desc:'푸른 수평선과 따뜻한 빛이 머무는 조용한 공간.',image:photo,price:240000,pool:true},{name:'고요한 오후',loc:'제주특별자치도 · 제주시',desc:'바쁜 일정 대신, 공간의 온도에 집중하는 시간.',image:roomPhoto,price:180000,pool:false},{name:'바다의 문장',loc:'제주특별자치도 · 서귀포시',desc:'느린 하루를 위한, 자연과 가까운 머무름.',image:photo,price:280000,pool:true},{name:'온 스테이',loc:'제주특별자치도 · 제주시',desc:'빛과 여백으로 채운 당신의 새로운 여행.',image:roomPhoto,price:210000,pool:false}];
function filterMarkup(){return `<div class="filter-group"><fieldset><legend>숙소 편의시설</legend><label><input type="checkbox" data-filter="pool" ${state.pool?'checked':''}> 수영장</label><label><input type="checkbox" data-filter="parking"> 주차</label><label><input type="checkbox" data-filter="breakfast"> 조식</label></fieldset></div><div class="filter-group"><fieldset><legend>기본 1박 가격</legend><label>최소<input aria-label="최소 기본 가격" type="number" min="0" placeholder="금액 입력"></label><label>최대<input aria-label="최대 기본 가격" type="number" min="0" placeholder="금액 입력"></label></fieldset><p class="filter-note">날짜별 적용 요금이나 숙박 총액이 아닌 객실 기본 가격 기준입니다.</p></div><button class="outline" data-action="filterApply">조건 적용</button>`}
function cards(){return stays.filter(x=>!state.pool||x.pool).map(x=>`<article class="stay-card"><a href="?view=detail" data-go="detail" class="stay-photo"><img src="${x.image}" alt="AI 생성 숙소 콘셉트 사진"><span class="mock-chip">CONCEPT IMAGE</span></a><div class="stay-copy"><p class="location">${x.loc}</p><h2><a href="?view=detail" data-go="detail">${x.name}</a></h2><p class="desc">${x.desc}</p><div class="amenities"><span>주차</span><span>조식</span>${x.pool?'<span>수영장</span>':''}</div><div class="stay-bottom"><p class="price">${currency(x.price)}<small>객실 별도 조회 예시 · 기본 1박 / 통화 미제공</small></p><a class="arrow-link" href="?view=detail" data-go="detail">객실 보기 ↗</a></div></div></article>`).join('')}
function resultContent(){if(state.result==='empty')return '<div class="empty-display"><h2>조건에 맞는 숙소가 없어요.</h2><p>날짜나 편의시설 조건을 조금 넓혀보세요.</p><button class="text-btn" data-action="resetResults">조건 다시 살펴보기</button></div>';if(state.result==='error')return '<div class="empty-display" role="alert"><h2>잠시 연결이 어려워요.</h2><p>입력하신 일정은 그대로 유지하고 있어요.</p><button class="primary" data-action="resetResults">다시 불러오기</button></div>';if(state.result==='loading')return '<div class="result-grid loading-preview" role="status" aria-label="숙소를 불러오는 중"><div><div class="skeleton"></div><div class="skeleton"></div></div><div><div class="skeleton"></div><div class="skeleton"></div></div></div>';return `<div class="result-grid">${cards()}</div><nav class="pagination" aria-label="검색 페이지"><button disabled aria-label="이전 페이지">←</button><button aria-current="page">1</button><button disabled aria-label="다음 페이지">→</button></nav>`}
function search(){return `${mast(false)}<div class="demo-note">가상 숙소 4개로 구성한 비교 화면 · 사진/가격은 실제 매물이 아닙니다. 객실 가격은 숙소 검색 응답에 없어 별도 조회 구성이 필요합니다.</div><header class="page-heading"><p class="eyebrow">FIND YOUR OWN PACE</p><h1>A place to be.</h1><p>머물고 싶은 곳을, 당신의 속도로 찾아보세요.</p></header><div class="compact-search">${searchbar()}</div><div class="search-layout"><aside class="filters"><h2>원하는 머무름</h2>${filterMarkup()}</aside><section aria-label="숙소 검색 결과"><div class="result-tools"><span>${state.city?escape(state.city):'전체 지역'} · 가상 숙소 ${state.pool?2:4}곳</span><button class="mobile-filter" data-action="filters">필터 ☰</button><label>정렬 <select id="sort" aria-label="숙소 정렬"><option>이름순</option><option>ID순</option></select></label></div><div class="state-demo" aria-label="검토용 결과 상태"><span>시안 상태</span>${['normal','loading','empty','error'].map((x,i)=>`<button data-result="${x}" class="${state.result===x?'active':''}">${['결과','로딩','빈 결과','오류'][i]}</button>`).join('')}</div><div id="results">${resultContent()}</div><p class="results-footnote">가격·가용성은 예시입니다. 실제 예약에서는 Backend의 적용 요금과 재고를 다시 확인합니다.</p></section></div>${footer()}`}
const roomNames=['코스탈 더블','테라스 스위트'];
function roomCard(i){return `<article class="room-card ${state.room===i+1?'selected':''}"><img src="${roomPhoto}" alt="가상 객실 이미지, 실제 객실 정보 아님"><div class="room-card-copy"><p class="eyebrow">ROOM ${String(i+1).padStart(2,'0')}</p><h3>${roomNames[i]}</h3><p>최대 ${i?4:2}명 · 와이파이 · 에어컨</p><button class="text-btn" data-room="${i+1}">객실 자세히 보기 ↗</button><div class="room-price"><p class="price">${currency(i?320000:240000)}<small>가상 기본 1박 · 통화 미제공</small></p><button class="outline" data-select-room="${i+1}" ${state.guests>(i?4:2)?'disabled':''}>${state.room===i+1?'선택됨':'선택'}</button></div></div></article>`}
function detail(){const base=state.room===2?320000:240000;return `${mast(false)}<div class="demo-note">가상 숙소·이미지·가용성·금액 예시 · 갤러리는 신규 이미지 데이터가 필요한 제안입니다.</div><div class="breadcrumb"><a href="?view=search" data-go="search">숙소 검색</a> / 제주특별자치도 / 서해의 여백</div><header class="detail-title"><div><p class="eyebrow">SLOW DAYS, BY THE SEA</p><h1>서해의 여백</h1><p>제주특별자치도 서귀포시 · 조용히 머무는 시간</p></div><button class="text-btn" data-action="gallery">사진 살펴보기 ↗</button></header><div class="gallery"><div><img src="${photo}" alt="가상 숙소의 바다와 수영장"></div><div><img src="${roomPhoto}" alt="가상 객실 내부"></div><button class="gallery-more" data-action="gallery">사진 2장 보기 ↗</button></div><div class="detail-body"><div><nav class="detail-nav"><a href="#about">숙소 소개</a><a href="#rooms">객실 선택</a><a href="#info">이용 안내</a></nav><section id="about"><h2>바다가 하루의 배경이 되는 곳.</h2><p class="intro">커다란 창 너머로 들어오는 햇살, 고요히 흐르는 바다.<br>비워낸 공간 속에서 온전히 쉬어가는 시간을 만나보세요.<br>서두르지 않는 여행을 위한 작은 머무름입니다.</p><div class="amenities"><span>주차</span><span>조식</span><span>수영장</span></div><div class="info-pairs" id="info"><p><small>체크인</small>15:00</p><p><small>체크아웃</small>11:00</p><p><small>현지 시간</small>Asia/Seoul</p></div></section><section class="room-section" id="rooms"><h2>당신에게 맞는 객실</h2><p class="notice">${range()} · ${nights()}박 · ${state.guests}명 · 가용성은 시안용 예시</p>${roomCard(0)}${roomCard(1)}</section></div><aside class="book-panel"><h2>머무를 시간을 선택하세요.</h2><button class="single-choice" data-action="dates"><span><small>체크인 — 체크아웃</small>${range()} · ${nights()}박</span><span>⌄</span></button><button class="single-choice" data-action="guests"><span><small>전체 숙박 인원</small>${state.guests}명</span><span>⌄</span></button><p class="available">${state.room?roomNames[state.room-1]+' 선택됨':'객실을 비교하고 선택해 주세요.'}</p>${state.room?`<div class="sumline"><span>가상 예상액 · ${nights()}박</span><strong>${currency(base*nights())}</strong></div><p class="fine">금액/통화는 실제 예약 정보가 아닙니다.</p>`:''}<button class="primary" data-action="book" ${!state.room?'disabled':''}>선택한 객실로 계속하기 ↗</button><p class="fine">예약은 아직 생성되지 않습니다.<br>날짜별 적용 금액과 최종 가용성은 서버에서 확인합니다.</p></aside></div><div class="mobile-book"><span>${state.room?roomNames[state.room-1]:range()+' · '+state.guests+'명'}</span><button class="primary" data-action="${state.room?'book':'roomScroll'}">${state.room?'예약 정보 확인':'객실 선택'} ↗</button></div>${footer()}`}
function updateUrl(push=false){const q=new URLSearchParams({view:state.view,palette:state.palette,city:state.city,in:state.start,out:state.end,guests:String(state.guests)});history[push?'pushState':'replaceState'](null,'',`?${q}`)}
function render(scroll=false){document.body.dataset.palette=state.palette;document.getElementById('palette').value=state.palette;document.querySelectorAll('[data-view]').forEach(b=>{if(b.dataset.view===state.view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});page.innerHTML=state.view==='a1'?home(false):state.view==='a2'?home(true):state.view==='search'?search():detail();updateUrl();if(scroll)window.scrollTo(0,0)}
function go(view){state.view=view;render(true)}
let draftStart,draftEnd,editing='start',month=10,year=2026,draftGuests=2;
function openDialog(id){const d=document.getElementById(id);if(!d.open)d.showModal();return d}
function heading(id,title){return `<div class="dialog-heading"><h2 id="${id}-title">${title}</h2><button class="close" data-close="${id}" aria-label="닫기">×</button></div>`}
function monthMarkup(offset){const first=new Date(Date.UTC(year,month+offset,1)),y=first.getUTCFullYear(),m=first.getUTCMonth(),count=new Date(Date.UTC(y,m+1,0)).getUTCDate();let html=`<div class="month"><div class="month-name">${y}년 ${m+1}월</div><div class="calendar">${'일월화수목금토'.split('').map(s=>`<small>${s}</small>`).join('')}${'<span></span>'.repeat(first.getUTCDay())}`;for(let day=1;day<=count;day++){const v=`${y}-${String(m+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;const edge=v===draftStart||v===draftEnd,between=v>draftStart&&v<draftEnd;html+=`<button data-day="${v}" class="${edge?'edge':between?'range':''}" aria-label="${m+1}월 ${day}일${v===draftStart?' 체크인':v===draftEnd?' 체크아웃':''}" aria-pressed="${edge}">${day}</button>`}return html+'</div></div>'}
function renderDates(){const d=document.getElementById('dates');d.innerHTML=heading('dates','언제 머무르시나요?')+`<div class="date-tabs"><button data-edit="start" class="${editing==='start'?'active':''}"><small>체크인</small>${fmt(draftStart)}</button><button data-edit="end" class="${editing==='end'?'active':''}"><small>체크아웃</small>${fmt(draftEnd)}</button></div><div class="month-nav"><button data-month="-1" aria-label="이전 달">←</button><span class="policy-note">최소 1박 · 날짜 범위 선택</span><button data-month="1" aria-label="다음 달">→</button></div><div class="months">${monthMarkup(0)}${monthMarkup(1)}</div><p class="notice" role="status">${fmt(draftStart)} 체크인 → ${fmt(draftEnd)} 체크아웃 · ${Math.round((Date.parse(draftEnd)-Date.parse(draftStart))/86400000)}박</p><div class="dialog-bottom"><span>체크인 변경 시 유효한 체크아웃은 유지해요.</span><button class="primary" data-action="applyDates">일정 적용</button></div>`}
function openDates(){draftStart=state.start;draftEnd=state.end;editing='start';const d=new Date(state.start+'T00:00:00Z');year=d.getUTCFullYear();month=d.getUTCMonth();renderDates();openDialog('dates')}
function renderGuests(){document.getElementById('guests').innerHTML=heading('guests','몇 분이 함께하시나요?')+`<div class="stepper"><div><strong>전체 숙박 인원</strong><p class="notice">성인·아동을 합한 전체 인원</p></div><div class="step-controls"><button data-guest="-1" aria-label="인원 줄이기" ${draftGuests<=1?'disabled':''}>−</button><output aria-live="polite">${draftGuests}</output><button data-guest="1" aria-label="인원 늘리기" ${draftGuests>=2147483647?'disabled':''}>+</button></div></div><div class="dialog-bottom"><span>객실별 최대 인원은 객실 선택에서 확인해요.</span><button class="primary" data-action="applyGuests">인원 적용</button></div>`}
function openRoom(i,galleryOnly=false){const index=Number(i)||1;const d=document.getElementById('room');d.innerHTML=heading('room',galleryOnly?'공간을 살펴보세요':roomNames[index-1])+`<img src="${galleryOnly?photo:roomPhoto}" alt="AI 생성 콘셉트 이미지"><div class="room-content">${galleryOnly?`<img src="${roomPhoto}" alt="가상 객실 이미지"><p class="notice">가상의 동일 숙소를 표현한 AI 이미지 2장입니다. 실제 매물 사진이 아닙니다.</p>`:`<div class="metadata"><p>최대 ${index===2?4:2}명</p><p>기본 1박 ${currency(index===2?320000:240000)}</p><p>와이파이 · 에어컨</p><p>운영 상태 ACTIVE · 가상 값</p></div><div class="mock-info"><strong>신규 데이터 확장 표현 예시</strong><p>객실 소개 / 침대 구성 / 면적 / 전망 / 사진 갤러리는 현재 Room DTO에 없습니다. 위 이미지는 실제 침대·전망을 증명하지 않습니다. 구현 시 Backend·DB·Admin 확장이 필요합니다.</p></div><button class="primary" data-select-room="${index}" ${state.guests>(index===2?4:2)?'disabled':''}>${state.guests>(index===2?4:2)?'선택 인원이 정원을 초과해요':'이 객실 선택하기'} ↗</button>`}</div>`;d.showModal()}
function booking(){const d=document.getElementById('booking');d.innerHTML=heading('booking','여행의 다음 장으로.')+`<p>선택한 일정을 한 번 더 확인해 주세요.</p><div class="booking-preview"><h3>서해의 여백 · ${roomNames[state.room-1]}</h3><p>${range()} · ${nights()}박 · ${state.guests}명</p><p>시안용 예상액 ${currency((state.room===2?320000:240000)*nights())} · 통화 미제공</p></div><p class="notice">여기까지가 독립 디자인 시안입니다. 로그인·투숙객 입력·실제 예약 API와 연결되지 않으며 예약은 생성되지 않습니다.</p><button class="primary" data-close="booking">확인하고 시안으로 돌아가기</button>`;d.showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.go){e.preventDefault();go(b.dataset.go);return}if(b.dataset.view){go(b.dataset.view);return}if(b.dataset.close){document.getElementById(b.dataset.close).close();return}if(b.dataset.result){state.result=b.dataset.result;render();return}if(b.dataset.room){openRoom(b.dataset.room);return}if(b.dataset.selectRoom){state.room=Number(b.dataset.selectRoom);document.getElementById('room').close();const pos=window.scrollY;render();window.scrollTo(0,pos);document.getElementById('announcer').textContent=roomNames[state.room-1]+' 선택됨';return}if(b.dataset.edit){editing=b.dataset.edit;renderDates();return}if(b.dataset.month){month+=Number(b.dataset.month);renderDates();return}if(b.dataset.day){const v=b.dataset.day;if(editing==='start'){draftStart=v;if(draftEnd<=draftStart)draftEnd=addDays(draftStart,1);editing='end'}else if(v<=draftStart){draftStart=v;draftEnd=addDays(v,1);editing='end'}else{draftEnd=v}renderDates();document.querySelector(`[data-day="${v}"]`)?.focus();return}if(b.dataset.guest){draftGuests=Math.max(1,Math.min(2147483647,draftGuests+Number(b.dataset.guest)));renderGuests();document.querySelector(`#guests [data-guest="${b.dataset.guest}"]`)?.focus();return}switch(b.dataset.action){case'dates':openDates();break;case'guests':draftGuests=state.guests;renderGuests();openDialog('guests');break;case'applyDates':state.start=draftStart;state.end=draftEnd;state.room=0;document.getElementById('dates').close();render();break;case'applyGuests':state.guests=draftGuests;state.room=0;document.getElementById('guests').close();render();break;case'gallery':openRoom(1,true);break;case'book':if(state.room)booking();break;case'roomScroll':document.getElementById('rooms')?.scrollIntoView({behavior:'smooth'});break;case'filters':document.getElementById('filters').innerHTML=heading('filters','원하는 머무름')+filterMarkup();openDialog('filters');break;case'filterApply':document.getElementById('filters').close();state.result='normal';render();break;case'resetResults':state.result='normal';state.pool=false;render();break;case'login':document.getElementById('booking').innerHTML=heading('booking','독립 시안 안내')+'<p>로그인 화면은 이번 핵심 시안 범위에 포함되지 않습니다. 실제 인증과 연결하지 않습니다.</p>';openDialog('booking');break}});
document.addEventListener('submit',e=>{if(!e.target.matches('.searchbar'))return;e.preventDefault();state.city=new FormData(e.target).get('city').trim();state.room=0;go('search')});
document.addEventListener('change',e=>{if(e.target.id==='palette'){state.palette=e.target.value;render()}if(e.target.dataset.filter==='pool'){state.pool=e.target.checked}});
window.addEventListener('popstate',()=>{const q=new URLSearchParams(location.search);if(['a1','a2','search','detail'].includes(q.get('view')))state.view=q.get('view');render()});
render();
